--[[
  Lua Shield Ultra v4.0 — AES-256-CTR Encrypted Loader
  PBKDF2-SHA256 (300K) + FNV-1a Integrity + Pure-Lua AES
]]--
local _LS = {}
_LS.K1 = {19,27,234,64,37,126,251,177,39,65,150,188,98,178,188,70,210,0,185,250,20,145,148,224,44,61,8,154,28,219,225,13}
_LS.K2 = {102,11,12,192,184,54,97,123,84,71,39,152,26,248,144,166,219,86,157,110,118,200,147,156,246,215,136,7,195,62,220,250}
_LS.P = ""

--[=[ Lua Shield Ultra — Core Utils ]=]
local sbyte, schar, ssub = string.byte, string.char, string.sub
local tconcat = table.concat
local floor = math.floor

local function _b64d(s)
  local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
  s = s:gsub('[^' .. b .. '=]', '')
  local r = {}
  local ri = 0
  for i = 1, #s, 4 do
    local c1, c2, c3, c4 = sbyte(s, i, i + 3)
    local n = (b:find(schar(c1)) - 1) * 262144 + (b:find(schar(c2)) - 1) * 4096
    if c3 and c3 ~= 61 then n = n + (b:find(schar(c3)) - 1) * 64 end
    if c4 and c4 ~= 61 then n = n + (b:find(schar(c4)) - 1) end
    ri = ri + 1; r[ri] = schar(floor(n / 65536) % 256)
    if c3 and c3 ~= 61 then ri = ri + 1; r[ri] = schar(floor(n / 256) % 256) end
    if c4 and c4 ~= 61 then ri = ri + 1; r[ri] = schar(n % 256) end
  end
  return tconcat(r)
end

local function _fnv1a(s)
  local h = 2166136261
  for i = 1, #s do
    h = bit32.band(bit32.bxor(h, sbyte(s, i)) * 16777619, 0xFFFFFFFF)
  end
  return h
end


--[=[ Lua Shield Ultra — Pure-Lua AES-256 (CTR mode) + Base64 + FNV-1a ]=]
local band, bxor, lshift, rshift = bit32.band, bit32.bxor, bit32.lshift, bit32.rshift
local sbyte, schar, ssub = string.byte, string.char, string.sub
local tconcat = table.concat
local floor = math.floor

local _SBOX = {
0x63,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
