0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,
0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,
0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16}

local _RCON = {0x01,0x02,0x04,0x08,0x10,0x20,0x40,0x80,0x1b,0x36}

local function _xtime(a)
  local r = lshift(a, 1)
  if band(a, 0x80) ~= 0 then r = bxor(r, 0x11b) end
  return band(r, 0xff)
end

local function _gmul(a, b)
  local p = 0
  for _ = 1, 8 do
    if band(b, 1) ~= 0 then p = bxor(p, a) end
    a = _xtime(a)
    b = rshift(b, 1)
  end
  return p
end

local function _expandKey(key)
  -- key: string 32 bytes -> round keys: 15 x 16 bytes (flat array of 240)
  local w = {}
  for i = 0, 7 do
    local o = i * 4
    w[i] = { sbyte(key, o+1), sbyte(key, o+2), sbyte(key, o+3), sbyte(key, o+4) }
  end
  for i = 8, 59 do
    local t = { w[i-1][1], w[i-1][2], w[i-1][3], w[i-1][4] }
    if i % 8 == 0 then
      t = { _SBOX[t[2]+1], _SBOX[t[3]+1], _SBOX[t[4]+1], _SBOX[t[1]+1] }
      t[1] = bxor(t[1], _RCON[floor(i/8)])
    elseif i % 8 == 4 then
      t = { _SBOX[t[1]+1], _SBOX[t[2]+1], _SBOX[t[3]+1], _SBOX[t[4]+1] }
    end
    local p = w[i-8]
    w[i] = { bxor(p[1], t[1]), bxor(p[2], t[2]), bxor(p[3], t[3]), bxor(p[4], t[4]) }
  end
  local rk = {}
  for i = 0, 59 do
    local o = i * 4
    rk[o+1], rk[o+2], rk[o+3], rk[o+4] = w[i][1], w[i][2], w[i][3], w[i][4]
  end
  return rk
end

local function _encryptBlock(inp, rk)
  -- inp: 16-byte array (1-indexed), rk: 240-byte flat array
  local s = {}
  for i = 1, 16 do s[i] = bxor(inp[i], rk[i]) end
  for round = 1, 13 do
    -- SubBytes
    for i = 1, 16 do s[i] = _SBOX[s[i]+1] end
    -- ShiftRows (state[r + 4c])
    local t = {}
    for r = 0, 3 do
      for c = 0, 3 do
        t[r + 4*c + 1] = s[r + 4*((c + r) % 4) + 1]
      end
    end
    s = t
    -- MixColumns
    for c = 0, 3 do
      local o = 4*c
      local a0, a1, a2, a3 = s[o+1], s[o+2], s[o+3], s[o+4]
      s[o+1] = bxor(bxor(_xtime(a0), bxor(_xtime(a1), a1)), bxor(a2, a3))
      s[o+2] = bxor(bxor(a0, _xtime(a1)), bxor(bxor(_xtime(a2), a2), a3))
      s[o+3] = bxor(bxor(bxor(a0, a1), _xtime(a2)), bxor(_xtime(a3), a3))
      s[o+4] = bxor(bxor(bxor(_xtime(a0), a0), bxor(a1, a2)), _xtime(a3))
    end
    -- AddRoundKey
    local ro = round * 16
    for i = 1, 16 do s[i] = bxor(s[i], rk[ro + i]) end
  end
  -- final round
  for i = 1, 16 do s[i] = _SBOX[s[i]+1] end
  local t = {}
  for r = 0, 3 do
    for c = 0, 3 do
      t[r + 4*c + 1] = s[r + 4*((c + r) % 4) + 1]
    end
  end
  local ro = 14 * 16
  for i = 1, 16 do t[i] = bxor(t[i], rk[ro + i]) end
  return t
end

local function _incCounter(ctr)
  for i = 16, 1, -1 do
    ctr[i] = band(ctr[i] + 1, 0xff)
    if ctr[i] ~= 0 then break end
  end
end

local function _aes256ctr(data, key, iv)
  -- data: string, key: string(32), iv: string(16)
  local rk = _expandKey(key)
  local ctr = {}
  for i = 1, 16 do ctr[i] = sbyte(iv, i) end
  local out = {}
  local n = #data
  local pos = 1
  local bi = 0
  while pos <= n do
    local ks = _encryptBlock(ctr, rk)
    _incCounter(ctr)
    local chunk = math.min(16, n - pos + 1)
    for j = 0, chunk - 1 do
      bi = bi + 1
      out[bi] = schar(bxor(sbyte(data, pos + j), ks[j + 1]))
    end
    pos = pos + 16
  end
  return tconcat(out)
end


local function _ls_key()
  local kb = {}
  for i = 1, 32 do kb[i] = bit32.bxor(_LS.K1[i], _LS.K2[i]) end
  return string.char((table.unpack or unpack)(kb, 1, 32))
end
local function _ls_run()
  local raw = _b64d(_LS.P)
  local iv = ssub(raw, 17, 32)
  local ct = ssub(raw, 33)
  local pt = _aes256ctr(ct, _ls_key(), iv)
  local h = sbyte(pt, 1) + sbyte(pt, 2) * 256 + sbyte(pt, 3) * 65536 + sbyte(pt, 4) * 16777216
  local body = ssub(pt, 5)
  if _fnv1a(body) ~= h then error("[Lua Shield Ultra] Integrity check failed!") end
  local ld = loadstring or load
  local f, e = ld(body)
  if not f then error("[Lua Shield Ultra] Compile error: " .. tostring(e)) end
  return f()
end
_ls_run()
